Here is the commit message:
iio: sca3000: Fix a resource leak in sca3000_probe()

spi->irq from request_threaded_irq() not released when
iio_device_register() fails. Add an return value check and jump to a
common error handler when iio_device_register() fails.

Fixes: 9a4936dc89a3 ("staging:iio:accel:sca3000 Tidy up probe order to avoid a race.")
Signed-off-by: Harshit Mogalapalli <harshit.m.mogalapalli@oracle.com>
Reviewed-by: Andy Shevchenko <andriy.shevchenko@intel.com>
Signed-off-by: Jonathan Cameron <Jonathan.Cameron@huawei.com>

Here is the root cause:
The return value of iio_device_register() was not checked and the function directly returned it, bypassing the error cleanup path for the IRQ. This caused a resource leak (IRQ not freed) when device registration fails.

Here is the patch:

 static int sca3000_probe(struct spi_device *spi)
 {
 	int ret;
 	struct sca3000_state *st;
 	struct iio_dev *indio_dev;

 	indio_dev = devm_iio_device_alloc(&spi->dev, sizeof(*st));
 	if (!indio_dev)
 		return -ENOMEM;

 	st = iio_priv(indio_dev);
 	spi_set_drvdata(spi, indio_dev);
 	st->us = spi;
 	mutex_init(&st->lock);
 	st->info = &sca3000_spi_chip_info_tbl[spi_get_device_id(spi)
 					      ->driver_data];

 	indio_dev->name = spi_get_device_id(spi)->name;
 	indio_dev->info = &sca3000_info;
 	if (st->info->temp_output) {
 		indio_dev->channels = sca3000_channels_with_temp;
 		indio_dev->num_channels =
 			ARRAY_SIZE(sca3000_channels_with_temp);
 	} else {
 		indio_dev->channels = sca3000_channels;
 		indio_dev->num_channels = ARRAY_SIZE(sca3000_channels);
 	}
 	indio_dev->modes = INDIO_DIRECT_MODE;

 	ret = devm_iio_kfifo_buffer_setup(&spi->dev, indio_dev,
 					  &sca3000_ring_setup_ops);
 	if (ret)
 		return ret;

 	if (spi->irq) {
 		ret = request_threaded_irq(spi->irq,
 					   NULL,
 					   &sca3000_event_handler,
 					   IRQF_TRIGGER_FALLING | IRQF_ONESHOT,
 					   "sca3000",
 					   indio_dev);
 		if (ret)
 			return ret;
 	}
 	ret = sca3000_clean_setup(st);
 	if (ret)
 		goto error_free_irq;

 	ret = sca3000_print_rev(indio_dev);
 	if (ret)
 		goto error_free_irq;

-	return iio_device_register(indio_dev);
+	ret = iio_device_register(indio_dev);
+	if (ret)
+		goto error_free_irq;
+
+	return 0;

 error_free_irq:
 	if (spi->irq)
 		free_irq(spi->irq, indio_dev);

 	return ret;
 }



